import React, { useState, useEffect, useRef } from "react";

const PHOTO = "data:image/jpeg;base64,";
const CV = "data:application/pdf;base64,";
const PROTO_LINGO = "";
const PROTO_SCRIB = "";
// ↓ paste each project's landing-page URL here to activate the "Landing page ↗" links
const SITE_LINGO = "";
const SITE_SCRIB = "";

// ↓ paste each paper's URL here to activate the "Read paper ↗" links
const PAPER_01 = "https://github.com/mariachiaracavagna/Research/blob/main/ECS784_C1_Cavagna_Report.pdf";
const PAPER_02 = "";
const SHOT_JOURNAL = "data:image/png;base64,";
const SHOT_ANALYTICS = "data:image/png;base64,";
const SHOT_THEMES = "data:image/png;base64,";
const SHOT_PLANS = "data:image/png;base64,";
const SHOT_ENTRIES = "data:image/png;base64,";
const VIDEO_LINGO = "data:video/mp4;base64,";
const SHOT_L_BREAKDOWN = "data:image/jpeg;base64,";
const SHOT_L_VERB = "data:image/jpeg;base64,";
const SHOT_L_LANDING = "data:image/jpeg;base64,";
const SHOT_FIXIT_EXP = "data:image/png;base64,";
const REDUCE = typeof window!=="undefined" && window.matchMedia("(prefers-reduced-motion:reduce)").matches;

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700;800;900&family=Space+Mono:wght@400;700&display=swap');

:root{
  --paper:#F3F1EE; --ink:#15140E; --acc:#FF1E63;
  --mut:#5F5D53; --line:#C7C4B8; --hair:rgba(21,20,14,.34);
  --grid:rgba(21,20,14,.06); --plate:#E2E0D7;
  --gfine:rgba(21,20,14,.05); --gmaj:rgba(21,20,14,.13);
  --disp:'Archivo','Helvetica Neue',Arial,sans-serif;
  --mono:'Space Mono',ui-monospace,Menlo,monospace;
}
*{box-sizing:border-box}
.pf,.pf *{margin:0;padding:0}
.pf{background:var(--paper);color:var(--ink);font-family:var(--disp);
  -webkit-font-smoothing:antialiased;scroll-behavior:smooth;min-height:100vh;overflow-x:hidden;padding-top:46px}
.pf section,.pf header{scroll-margin-top:52px}
.pf a{color:inherit;text-decoration:none}
.pf ::selection{background:var(--acc);color:#fff}
.pf :focus-visible{outline:2px solid var(--acc);outline-offset:3px}
.mono{font-family:var(--mono)}
.acc{color:var(--acc)}

.sheet{max-width:1340px;margin:0 auto;border-left:1px solid var(--line);
  border-right:1px solid var(--line);position:relative}
.crop{position:absolute;width:13px;height:13px;pointer-events:none;z-index:3}
.crop::before,.crop::after{content:"";position:absolute;background:var(--ink)}
.crop::before{width:13px;height:1px;top:0}.crop::after{width:1px;height:13px;left:0}
.crop.tl{top:-1px;left:-1px}
.crop.tr{top:-1px;right:-1px}.crop.tr::before{right:0;left:auto}.crop.tr::after{right:0;left:auto}

.scale{position:relative;height:24px;border-bottom:1px solid var(--line);display:flex;align-items:center}
.scale::before{content:"";position:absolute;left:0;right:0;bottom:0;height:5px;
  background:repeating-linear-gradient(to right,var(--hair) 0 1px,transparent 1px 8px)}
.scale::after{content:"";position:absolute;left:0;right:0;bottom:0;height:10px;
  background:repeating-linear-gradient(to right,var(--ink) 0 1px,transparent 1px 48px)}
.scale .cap{position:relative;z-index:2;padding:0 14px;background:var(--paper);
  font-family:var(--mono);font-size:.58rem;letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
.scale .cap.r{margin-left:auto}

.dim{display:flex;align-items:center;gap:12px;font-family:var(--mono);
  font-size:.6rem;letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
.dim .ln{flex:1;height:1px;background:var(--hair);position:relative}
.dim .ln::before,.dim .ln::after{content:"";position:absolute;top:-3px;width:1px;height:7px;background:var(--ink)}
.dim .ln::before{left:0}.dim .ln::after{right:0}

.nav{position:fixed;top:0;left:0;right:0;z-index:60;background:var(--paper);
  border-bottom:1px solid var(--ink);display:flex;align-items:stretch;
  justify-content:space-between;height:46px;font-family:var(--mono)}
.nav .brand{display:flex;align-items:center;gap:9px;padding:0 16px;font-size:.72rem;
  letter-spacing:.16em;text-transform:uppercase;border-right:1px solid var(--line)}
.nav .brand .sq{width:9px;height:9px;border:1px solid var(--ink)}
.nav .right{display:flex;margin-left:auto}
.nav .links{display:flex}
.nav .links a{display:flex;align-items:center;padding:0 15px;font-size:.64rem;
  letter-spacing:.18em;text-transform:uppercase;color:var(--mut);
  border-left:1px solid var(--line);transition:color .15s}
.nav .links a:hover{color:var(--ink)}
.nav .links a.on{color:var(--acc)}
.nav .cv{display:flex;align-items:center;padding:0 15px;font-size:.64rem;
  letter-spacing:.18em;text-transform:uppercase;color:var(--acc);
  border-left:1px solid var(--ink);font-weight:700}
.nav .cv:hover{background:var(--acc);color:#fff}

.band{display:flex;align-items:baseline;gap:16px;flex-wrap:wrap;padding:104px 26px 26px;border-bottom:1px solid var(--ink)}
#work .band{padding-top:280px}
.band .sh{font-family:var(--mono);font-size:.66rem;letter-spacing:.22em;text-transform:uppercase;color:var(--mut)}
.band .ti{font-weight:600;font-size:clamp(1.05rem,2.3vw,1.6rem);letter-spacing:-.008em}
.band .ct{margin-left:auto;font-family:var(--mono);font-size:.62rem;letter-spacing:.2em;color:var(--mut)}

.hero{display:grid;grid-template-columns:1fr 1fr;align-items:stretch}
.hero .L{padding:48px 26px 44px;display:flex;flex-direction:column}
.doc{font-family:var(--mono);font-size:.62rem;letter-spacing:.2em;text-transform:uppercase;color:var(--mut);margin-bottom:26px}
.name{font-weight:900;font-size:clamp(2.6rem,10.2vw,8.4rem);line-height:.86;letter-spacing:-.035em;text-transform:uppercase}
.name .l2{display:block}
.nameSm{font-family:var(--disp);font-weight:600;font-size:clamp(2.2rem,4.8vw,3.5rem);line-height:1.03;letter-spacing:-.016em;color:var(--ink)}
.lede{font-family:var(--disp);font-weight:500;font-size:clamp(1.12rem,2.1vw,1.5rem);line-height:1.25;letter-spacing:-.004em;color:var(--ink);margin-top:8px}
.dimwrap{margin:22px 0 2px}
.subs{margin-top:10px;font-family:var(--mono);font-size:.74rem;letter-spacing:.14em;text-transform:uppercase;color:var(--ink)}
.subs .a{color:var(--acc)}
.subs .d{color:var(--line)}
.tag{margin-top:18px;max-width:52ch;font-size:1.14rem;line-height:1.5;color:var(--ink)}
.tblock{margin-top:auto;padding-top:44px}
.tbcap{font-family:var(--mono);font-size:.56rem;letter-spacing:.2em;text-transform:uppercase;color:var(--mut);margin-bottom:6px}
.tb{border:1px solid var(--ink);display:grid;grid-template-columns:1fr;font-family:var(--mono);max-width:420px}
.tb .cell{padding:11px 14px;border-top:1px solid var(--line)}
.tb .cell:first-child{border-top:none}
.tb .cell.full{grid-column:1/-1}
.tb .v{font-size:.82rem;line-height:1.5;letter-spacing:.02em;color:var(--ink)}

.hero .R{display:flex;justify-content:flex-start;align-items:flex-end;padding:48px 26px 44px 0}
.pcard{width:248px;max-width:88%}
.plate{position:relative;aspect-ratio:4/5;overflow:hidden;border:1px solid var(--line);
  background-color:var(--plate);
  background-image:
  linear-gradient(var(--gfine) 1px,transparent 1px),linear-gradient(90deg,var(--gfine) 1px,transparent 1px),
  linear-gradient(var(--gmaj) 1px,transparent 1px),linear-gradient(90deg,var(--gmaj) 1px,transparent 1px);
background-size:5px 5px,5px 5px,25px 25px,25px 25px}
.plate img{width:100%;height:100%;object-fit:cover;object-position:center top;display:block;
  opacity:1;filter:contrast(1.14) saturate(1.04) brightness(1.02)}
.fig{position:absolute;left:12px;bottom:11px;background:var(--paper);padding:3px 8px;
  font-family:var(--mono);font-size:.58rem;letter-spacing:.14em;text-transform:uppercase;border:1px solid var(--ink)}
.tick{position:absolute;width:9px;height:9px;z-index:2}
.tick::before,.tick::after{content:"";position:absolute;background:var(--ink)}
.tick::before{width:9px;height:1px}.tick::after{width:1px;height:9px}
.tick.a{top:8px;left:8px}.tick.b{top:8px;right:8px}.tick.b::before,.tick.b::after{right:0}
.tick.c{bottom:8px;left:8px}.tick.c::before,.tick.c::after{bottom:0}
.tick.d{bottom:8px;right:8px}.tick.d::before,.tick.d::after{bottom:0;right:0}
.rmeta{padding:9px 12px;border:1px solid var(--line);border-top:none;width:100%;box-sizing:border-box;
  font-family:var(--mono);font-size:.58rem;letter-spacing:.16em;
  text-transform:uppercase;color:var(--mut);display:flex;justify-content:space-between}

.item{display:grid;grid-template-columns:1fr;border-bottom:1px solid var(--ink)}
.item .gut{padding:14px 26px;border-right:none;border-bottom:1px solid var(--line);
  display:flex;flex-direction:row;align-items:center;gap:12px}

/* products - three columns side by side */
.wgrid{display:grid;grid-template-columns:repeat(3,1fr);border-bottom:1px solid var(--ink)}
.wgrid .item{grid-template-columns:1fr;align-content:start;border-bottom:none;border-right:1px solid var(--line)}
.wgrid .item:last-child{border-right:none}
.wgrid .item .gut{flex-direction:row;align-items:center;gap:12px;padding:14px 20px;
  border-right:none;border-bottom:1px solid var(--line)}
.wgrid .item .main{grid-template-columns:1fr;gap:22px;padding:28px 20px 32px}
.wgrid .pcol{order:-1}

.wgrid .wtitle{font-size:clamp(1.25rem,1.9vw,1.65rem)}
.wgrid .wdesc{display:none}
.wgrid .moves{display:none}
.wgrid .spec .row{grid-template-columns:1fr;gap:4px}
.wgrid .spec .row:not(:last-child){display:none}
@media(max-width:960px){
  .wgrid{grid-template-columns:1fr}
  .wgrid .item{border-right:none;border-bottom:1px solid var(--ink)}
  .wgrid .item:last-child{border-bottom:none}
}

/* research - side by side */
.rgrid{display:grid;grid-template-columns:repeat(2,1fr);border-bottom:1px solid var(--ink)}
.rgrid .item{grid-template-columns:1fr;align-content:start;border-bottom:none;border-right:1px solid var(--line)}
.rgrid .item:last-child{border-right:none}
.rgrid .item .gut{padding:14px 20px}
.rgrid .item .main{grid-template-columns:1fr;gap:22px;padding:28px 20px 32px}
.rgrid .rd{margin-top:2px}
@media(max-width:960px){
  .rgrid{grid-template-columns:1fr}
  .rgrid .item{border-right:none;border-bottom:1px solid var(--ink)}
  .rgrid .item:last-child{border-bottom:none}
}
.pill{font-family:var(--mono);font-size:.58rem;letter-spacing:.14em;text-transform:uppercase;
  border:1px solid var(--ink);padding:4px 7px;align-self:center}
.gut .pill{margin-left:auto}
.ref{font-family:var(--mono);font-size:.86rem;letter-spacing:.1em;font-weight:700}
.ref .tot{color:var(--mut);opacity:.55;font-weight:400}
.item .main{padding:40px 26px;display:grid;grid-template-columns:1.15fr .85fr;gap:30px}
.wtitle{font-weight:600;font-size:clamp(1.5rem,3.4vw,2.4rem);line-height:1.02;letter-spacing:-.014em}
.wrole{margin-top:9px;font-family:var(--mono);font-size:.7rem;letter-spacing:.05em;color:var(--mut)}
.wdesc{margin-top:14px;font-size:.95rem;line-height:1.55;max-width:54ch;color:var(--ink)}
.oneliner{margin-top:8px;font-family:var(--disp);font-weight:500;font-size:clamp(.98rem,1.5vw,1.12rem);letter-spacing:-.004em;color:var(--ink)}
.moves{display:flex;flex-wrap:wrap;gap:6px;margin-top:16px}
.chip{font-family:var(--mono);font-size:.57rem;letter-spacing:.1em;text-transform:uppercase;border:1px solid var(--line);padding:5px 8px;color:var(--mut)}
.item:hover .chip{border-color:var(--hair)}
.pcol{display:flex;flex-direction:column;gap:8px}
.shot{position:relative;display:block;width:100%;padding:0;border:1px solid var(--line);overflow:hidden;
  appearance:none;-webkit-appearance:none;cursor:pointer;transition:border-color .15s;
  background-color:var(--plate);
  background-image:
  linear-gradient(var(--gfine) 1px,transparent 1px),linear-gradient(90deg,var(--gfine) 1px,transparent 1px),
  linear-gradient(var(--gmaj) 1px,transparent 1px),linear-gradient(90deg,var(--gmaj) 1px,transparent 1px);
  background-size:5px 5px,5px 5px,25px 25px,25px 25px}
.shot{aspect-ratio:1/1}
.shot img,.shot video{display:block;width:100%;height:100%;object-fit:cover;object-position:center top}
.shot .fig{position:absolute;left:10px;bottom:10px;background:var(--paper);padding:3px 8px;
  font-family:var(--mono);font-size:.56rem;letter-spacing:.14em;text-transform:uppercase;border:1px solid var(--ink)}
.shot .open{position:absolute;right:10px;top:10px;background:var(--paper);border:1px solid var(--ink);padding:3px 7px;
  font-family:var(--mono);font-size:.56rem;letter-spacing:.14em;text-transform:uppercase;color:var(--acc)}
.shot:hover{border-color:var(--acc)}
.shot.free{aspect-ratio:auto;border-color:transparent;background:none;overflow:visible;padding:8px 0}
.shot.free img{width:auto;max-width:100%;height:auto;max-height:440px;object-fit:contain;margin:0 auto}
.shot.free:hover{border-color:transparent}
.shot.free .fig{left:0;bottom:0}
.csmedia .shot.free img{max-height:none;width:100%}
.thumbs{display:flex;gap:6px}
.th{flex:1;position:relative;aspect-ratio:1/1;border:1px solid var(--line);padding:0;overflow:hidden;background:var(--plate);
  cursor:pointer;appearance:none;-webkit-appearance:none;transition:border-color .15s}
.th img{width:100%;height:100%;object-fit:cover;object-position:top}
.th .play{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;
  color:#fff;font-size:.7rem;text-shadow:0 1px 4px rgba(0,0,0,.7)}
.th:hover{border-color:var(--hair)}
.th.on{border-color:var(--acc)}
.thumbs.free{gap:12px;align-items:flex-start}
.thumbs.free .th{aspect-ratio:auto;border:none;background:none;overflow:visible;opacity:.5;transition:opacity .15s}
.thumbs.free .th img{width:100%;height:auto;object-fit:contain}
.thumbs.free .th:hover{opacity:.8}
.thumbs.free .th.on{opacity:1}
.shot.free.drop img{filter:drop-shadow(0 10px 26px rgba(21,20,14,.20)) drop-shadow(0 2px 6px rgba(21,20,14,.12))}
.thumbs.free.drop .th img{filter:drop-shadow(0 4px 12px rgba(21,20,14,.18))}
.spec{margin-top:18px;border-top:1px solid var(--line)}
.spec .row{display:grid;grid-template-columns:92px 1fr;gap:12px;padding:8px 0;border-bottom:1px solid var(--line);font-family:var(--mono)}
.spec .row .k{font-size:.58rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);padding-top:2px}
.spec .row .v{font-size:.76rem;letter-spacing:.02em}

.vplate{position:relative;border:1px solid var(--line);min-height:210px;width:100%;
  display:flex;align-items:center;justify-content:center;appearance:none;-webkit-appearance:none;font:inherit;color:inherit;
  background-color:var(--plate);
  background-image:
  linear-gradient(var(--gfine) 1px,transparent 1px),linear-gradient(90deg,var(--gfine) 1px,transparent 1px),
  linear-gradient(var(--gmaj) 1px,transparent 1px),linear-gradient(90deg,var(--gmaj) 1px,transparent 1px);
background-size:5px 5px,5px 5px,25px 25px,25px 25px;transition:border-color .15s}
.vplate .txt{font-family:var(--mono);font-size:.6rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);text-align:center;line-height:1.9}
.vplate:hover{border-color:var(--acc)}
.vplate:hover .txt{color:var(--acc)}
.vplate:hover .tick::before,.vplate:hover .tick::after{background:var(--acc)}
.plink{appearance:none;background:none;border:none;padding:0;font:inherit;color:var(--acc);cursor:pointer;letter-spacing:inherit}
.item:hover .pill{background:var(--acc);color:#fff;border-color:var(--acc)}
.item:hover .vplate .tick::before,.item:hover .vplate .tick::after{background:var(--acc)}

.rd{border:1px solid var(--ink);display:grid;grid-template-columns:repeat(2,1fr);
  background-color:var(--plate);
  background-image:
  linear-gradient(var(--gfine) 1px,transparent 1px),linear-gradient(90deg,var(--gfine) 1px,transparent 1px),
  linear-gradient(var(--gmaj) 1px,transparent 1px),linear-gradient(90deg,var(--gmaj) 1px,transparent 1px);
background-size:5px 5px,5px 5px,25px 25px,25px 25px}
.rd .m{padding:14px;border-top:1px solid var(--line);border-right:1px solid var(--line);background:transparent}
.rd .m:nth-child(-n+2){border-top:none}
.rd .m:nth-child(2n){border-right:none}
.rd .m .k{font-family:var(--mono);font-size:.55rem;letter-spacing:.18em;text-transform:uppercase;color:var(--mut)}
.rd .m .v{font-family:var(--mono);font-size:1.15rem;font-weight:700;margin-top:6px;letter-spacing:.01em}
.readlink{margin-top:14px;display:flex;justify-content:space-between;align-items:center;
  border:1px solid var(--ink);padding:11px 14px;font-family:var(--mono);font-size:.66rem;letter-spacing:.16em;text-transform:uppercase}
.readlink .v{color:var(--acc)}

.contact{padding:320px 26px 28px}
.bigmail{display:inline-block;font-weight:600;letter-spacing:-.016em;font-size:clamp(1rem,2.4vw,1.7rem);line-height:1.15;word-break:break-word}
.bigmail:hover{color:var(--acc)}
.clist{margin-top:44px;display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid var(--ink)}
.clist a,.clist .ci{padding:20px 16px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);font-family:var(--mono)}
.clist a:last-child{border-right:none}
.clist .ck{font-size:.56rem;letter-spacing:.2em;text-transform:uppercase;color:var(--mut)}
.clist .cv2{font-size:1rem;margin-top:9px;letter-spacing:.01em;color:var(--ink)}
.clist a:hover .cv2{color:var(--acc)}
.colophon{display:flex;justify-content:space-between;flex-wrap:wrap;gap:10px;padding:32px 0 14px;
  font-family:var(--mono);font-size:.58rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut)}

@media(max-width:860px){
  .hero{grid-template-columns:1fr}
  .hero .L{border-right:none;border-bottom:1px solid var(--ink)}
  .hero .R{justify-content:flex-start;padding:6px 20px 22px}
  .pcard{width:176px;max-width:64%}
  .item .gut{gap:12px;padding:13px 20px}
  .item .main{grid-template-columns:1fr!important;padding:34px 20px}
  .clist{grid-template-columns:repeat(2,1fr)}
  .clist a,.clist .ci{border-right:1px solid var(--line)}
  .band{padding:68px 20px 22px}
  #work .band{padding-top:170px}
  .contact{padding:200px 20px 24px}
}
@media(max-width:540px){ .nav .links{display:none} .clist{grid-template-columns:1fr} }
/* CAD crosshair cursor */
.cur{position:fixed;inset:0;z-index:9999;pointer-events:none;opacity:0;transition:opacity .18s;will-change:opacity}
.cur.show{opacity:1}
.cur .ret{position:absolute;left:0;top:0;width:26px;height:26px;margin:-13px 0 0 -13px}
.cur .ret::before,.cur .ret::after{content:"";position:absolute;left:50%;width:1px;height:9px;background:var(--ink);transform:translateX(-.5px)}
.cur .ret::before{top:0}.cur .ret::after{bottom:0}
.cur .ret i{position:absolute;top:50%;height:1px;width:9px;background:var(--ink);transform:translateY(-.5px)}
.cur .ret i.l{left:0}.cur .ret i.r{right:0}
.cur .rd{position:absolute;left:0;top:0;font-family:var(--mono);font-size:.56rem;
  letter-spacing:.14em;text-transform:uppercase;color:var(--mut);white-space:nowrap;
  background:none;border:none;padding:0}
.cur.hot .ret::before,.cur.hot .ret::after,.cur.hot .ret i{background:var(--acc)}
.cur.hot .rd{color:var(--acc)}
@media (hover:hover) and (pointer:fine){ .pf.cur-on,.pf.cur-on a,.pf.cur-on button{cursor:none} }
@media (hover:none),(pointer:coarse){ .cur{display:none!important} }
@media(prefers-reduced-motion:reduce){ .pf *{transition:none!important} .cur{display:none!important} }

/* title link + separators */
.titlelink{appearance:none;-webkit-appearance:none;background:none;border:none;padding:0;margin:0;font:inherit;color:inherit;cursor:pointer;letter-spacing:inherit;text-align:left}
.titlelink:hover{color:var(--acc)}
.sep{color:var(--line);margin:0 7px}

/* case study */
.csbar{display:flex;justify-content:space-between;align-items:center;padding:12px 26px;border-bottom:1px solid var(--ink);
  font-family:var(--mono);font-size:.64rem;letter-spacing:.16em;text-transform:uppercase}
.csbar .csbarref{color:var(--mut)}
.cshead{display:grid;grid-template-columns:1.5fr 1fr;border-bottom:1px solid var(--ink)}
.csheadL{padding:30px 26px;border-right:1px solid var(--line)}
.cstitle{font-weight:600;font-size:clamp(2rem,4.4vw,3.2rem);letter-spacing:-.016em;line-height:1.02;margin-bottom:2px}
.csheadR{padding:30px 26px}
.csmedia{border-bottom:1px solid var(--ink);padding:26px}
.csmediainner{max-width:860px;margin:0 auto;display:flex;flex-direction:column;gap:8px}
.csrow{display:grid;grid-template-columns:84px 1fr;border-bottom:1px solid var(--line)}
.csrow:last-child{border-bottom:1px solid var(--ink)}
.csn{padding:26px 16px;border-right:1px solid var(--line);font-family:var(--mono);font-size:.8rem;font-weight:700;color:var(--mut)}
.csc{padding:26px}
.csh{font-weight:600;font-size:1.18rem;letter-spacing:-.008em;margin-bottom:10px}
.csp{font-size:1rem;line-height:1.62;max-width:68ch;color:var(--ink)}
.declist{display:flex;flex-direction:column;gap:15px;margin-top:2px}
.dec{border-left:2px solid var(--line);padding-left:14px}
.dech{font-weight:600;font-size:.98rem;margin-bottom:3px}
.decb{font-size:.94rem;line-height:1.55;color:var(--ink);max-width:66ch}
.csfig{margin-top:18px;border:1px solid var(--line);background:var(--plate);max-width:660px}
.csfig img{display:block;width:100%;height:auto}
.figcap{font-family:var(--mono);font-size:.56rem;letter-spacing:.14em;text-transform:uppercase;color:var(--mut);padding:6px 8px;border-top:1px solid var(--line)}
.csfoot{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:20px 26px;
  font-family:var(--mono);font-size:.7rem;letter-spacing:.06em}
.life{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin-top:14px}
.lifebox{font-family:var(--mono);font-size:.62rem;letter-spacing:.09em;text-transform:uppercase;border:1px solid var(--line);padding:8px 10px;background:var(--plate)}
.lifebox.own{border-color:var(--acc);color:var(--acc)}
.lifearrow{color:var(--mut);font-family:var(--mono)}
@media(max-width:860px){
  .cshead{grid-template-columns:1fr}
  .csheadL{border-right:none;border-bottom:1px solid var(--line);padding:24px 20px}
  .csheadR{padding:22px 20px}
  .csbar{padding:11px 20px}
  .csmedia{padding:18px}
  .csrow{grid-template-columns:1fr}
  .csn{border-right:none;border-bottom:1px solid var(--line);padding:12px 20px}
  .csc{padding:20px}
  .csfoot{padding:18px 20px;flex-wrap:wrap}
}
`;

