function Ticks(){ return (<>{["a","b","c","d"].map(p=><span key={p} className={"tick "+p} aria-hidden="true"/>)}</>); }

function openProto(b64){
  try{
    const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));
    const url=URL.createObjectURL(new Blob([bytes],{type:"text/html;charset=utf-8"}));
    const win=window.open(url,"_blank","noopener");
    if(!win){
      const a=document.createElement("a");
      a.href=url; a.target="_blank"; a.rel="noopener";
      document.body.appendChild(a); a.click(); a.remove();
    }
    setTimeout(()=>URL.revokeObjectURL(url),60000);
  }catch(e){ console.error("prototype open failed",e); }
}
function openWork(w){ if(w.site){ window.open(w.site,"_blank","noopener"); } else if(w.proto){ openProto(w.proto); } }

function Gallery({w,onOpen,openLabel,ariaLabel,free,shadow}){
  const [i,setI]=useState(0);
  const shots=w.shots||[];
  const media=(w.video?[{type:"video",src:w.video,poster:shots[0]}]:[]).concat(shots.map(s=>({type:"image",src:s})));
  const isFree=free!==undefined?free:w.free;
  const cls=(isFree?" free":"")+(shadow?" drop":"");
  const canOpen=!!(onOpen||w.proto||w.site);
  const open=onOpen||(()=>openWork(w));
  const label=openLabel||(w.site?"Open ↗":(w.proto?"Prototype ↗":null));
  const aria=ariaLabel||`Open ${w.title}`;
  if(!media.length){
    return (
      <button className="vplate" style={{aspectRatio:w.ar}} onClick={open} aria-label={aria}>
        <Ticks/><div className="txt">Fig · {w.ref}<br/>{label}</div>
      </button>
    );
  }
  const cur=media[i];
  return (
    <>
      <button className={"shot"+cls} onClick={canOpen?open:undefined} aria-label={aria} disabled={!canOpen}>
        {cur.type==="video"
          ? <video src={cur.src} poster={cur.poster} muted loop playsInline autoPlay={!REDUCE} controls={REDUCE?true:undefined}/>
          : <img src={cur.src} alt={`${w.title} - screen ${i+1}`}/>}
        <span className="fig">Fig · {w.ref}.{i+1}</span>
        {label && <span className="open">{label}</span>}
      </button>
      {media.length>1 && (
        <div className={"thumbs"+cls}>
          {media.map((m,idx)=>(
            <button key={idx} className={"th"+(idx===i?" on":"")} onClick={()=>setI(idx)}
              aria-label={`View ${w.title} media ${idx+1}`}>
              <img src={m.type==="video"?m.poster:m.src} alt=""/>
              {m.type==="video" && <span className="play" aria-hidden="true">▶</span>}
            </button>
          ))}
        </div>
      )}
    </>
  );
}

function WorkCard({w,n,total,onCase}){
  return (
    <article className="item">
      <div className="gut">
        <span className="ref">{w.ref}<span className="tot">/{String(total).padStart(2,"0")}</span></span>
        <span className="pill">{w.plat}</span>
      </div>
      <div className="main">
        <div>
          <h3 className="wtitle"><button className="titlelink" onClick={()=>onCase(w.ref)}>{w.title}</button></h3>
          <p className="oneliner">{w.one}</p>
          <p className="wdesc">{w.desc}</p>
          {w.moves && <div className="moves">{w.moves.map(m=><span className="chip" key={m}>{m}</span>)}</div>}
          <div className="spec">
            <div className="row"><div className="k">Platform</div><div className="v">{w.plat}</div></div>
            <div className="row"><div className="k">Role</div><div className="v">{w.role}</div></div>
            <div className="row"><div className="k">Stack</div><div className="v">{w.stack}</div></div>
            {w.partner && <div className="row"><div className="k">Partner</div><div className="v">{w.partner}</div></div>}
            <div className="row"><div className="k">Year</div><div className="v">{w.year}</div></div>
            <div className="row"><div className="k">Links</div><div className="v">
              <button className="plink" onClick={()=>onCase(w.ref)}>Case study →</button>
              {w.proto && <><span className="sep">·</span><button className="plink" onClick={()=>openProto(w.proto)}>Prototype ↗</button></>}
              {w.site && <><span className="sep">·</span><a className="plink" href={w.site} target="_blank" rel="noreferrer">Landing page ↗</a></>}
            </div></div>
          </div>
        </div>
        <div className="pcol"><Gallery w={w} onOpen={()=>onCase(w.ref)} openLabel="Case study →" ariaLabel={`Open ${w.title} case study`}/></div>
      </div>
    </article>
  );
}

function LifecycleDiagram(){
  const stages=["Captured","Inbox","Loosely placed","Scheduled","Done"];
  return (
    <div>
      <div className="life" aria-label="Plan lifecycle">
        {stages.map((s,idx)=>(
          <React.Fragment key={s}>
            <div className={"lifebox"+(idx<3?" own":"")}>{s}</div>
            {idx<stages.length-1 && <span className="lifearrow">→</span>}
          </React.Fragment>
        ))}
      </div>
      <div className="figcap" style={{padding:"8px 0 0",border:"none"}}>Fig · lifecycle - the app owns the first three stages; only scheduled commitments sync out</div>
    </div>
  );
}

function CaseStudy({w,prev,next,onHome,onCase}){
  useEffect(()=>{ try{ window.scrollTo(0,0); }catch(e){} },[w.ref]);
  const s=w.study||{sections:[]};
  return (
    <div className="cs">
      <div className="csbar">
        <button className="plink" onClick={onHome}>← Products</button>
        <span className="csbarref">{w.ref} · Case study</span>
      </div>
      <div className="cshead">
        <div className="csheadL">
          <div className="doc">Sheet · {w.ref} / Case study</div>
          <h1 className="cstitle">{w.title}</h1>
          <p className="oneliner">{w.one}</p>
          <p className="tag" style={{maxWidth:"64ch"}}>{s.overview}</p>
          {w.moves && <div className="moves">{w.moves.map(m=><span className="chip" key={m}>{m}</span>)}</div>}
        </div>
        <div className="csheadR">
          <div className="tbcap">Spec</div>
          <div className="tb">
            <div className="cell"><div className="k">Platform</div><div className="v">{w.plat}</div></div>
            <div className="cell"><div className="k">Year</div><div className="v">{w.year}</div></div>
            <div className="cell full"><div className="k">Role</div><div className="v">{w.role}</div></div>
            <div className="cell full"><div className="k">Stack</div><div className="v">{w.stack}</div></div>
            {w.partner && <div className="cell full"><div className="k">Partner</div><div className="v">{w.partner}</div></div>}
            {(w.proto||w.site) && <div className="cell full"><div className="k">Links</div><div className="v">
              {w.proto && <button className="plink" onClick={()=>openProto(w.proto)}>Prototype ↗</button>}
              {w.site && <>{w.proto && <span className="sep">·</span>}<a className="plink" href={w.site} target="_blank" rel="noreferrer">Landing page ↗</a></>}
            </div></div>}
          </div>
        </div>
      </div>
      <div className="csmedia"><div className="csmediainner"><Gallery w={w} free={w.csfree||w.free} shadow={w.csfree}/></div></div>
      <div className="csbody">
        {s.sections.map(sec=>(
          <section className="csrow" key={sec.n}>
            <div className="csn">{sec.n}</div>
            <div className="csc">
              <h2 className="csh">{sec.label}</h2>
              {sec.body && <p className="csp">{sec.body}</p>}
              {sec.diagram==="lifecycle" && <LifecycleDiagram/>}
              {sec.decs && <div className="declist">{sec.decs.map(d=>(
                <div className="dec" key={d.h}><div className="dech">{d.h}</div><div className="decb">{d.b}</div></div>
              ))}</div>}
              {sec.figShot!=null && w.shots && w.shots[sec.figShot] && (
                <figure className="csfig">
                  <img src={w.shots[sec.figShot]} alt={`${w.title} - ${sec.label}`}/>
                  <figcaption className="figcap">Fig · {w.ref}.{sec.figShot+1} - {sec.label}</figcaption>
                </figure>
              )}
            </div>
          </section>
        ))}
      </div>
      <nav className="csfoot">
        {prev ? <button className="plink" onClick={()=>onCase(prev.ref)}>← {prev.title}</button> : <span/>}
        <button className="plink" onClick={onHome}>All work</button>
        {next ? <button className="plink" onClick={()=>onCase(next.ref)}>{next.title} →</button> : <span/>}
      </nav>
    </div>
  );
}

export default function Portfolio(){
  const [active,setActive] = useState("top");
  const [view,setView] = useState(()=> (typeof location!=="undefined" && location.hash.indexOf("#case/")===0) ? location.hash.slice(6) : null);
  useEffect(()=>{
    const onHash=()=>{ const h=location.hash; setView(h.indexOf("#case/")===0 ? h.slice(6) : null); };
    window.addEventListener("hashchange",onHash);
    return ()=>window.removeEventListener("hashchange",onHash);
  },[]);
  const goCase=(ref)=>{ location.hash="#case/"+ref; };
  const goHome=()=>{ location.hash="#work"; };
  useEffect(()=>{
    if(view) return;
    const h=(typeof location!=="undefined")?location.hash:"";
    if(h && h.indexOf("#case/")!==0){
      const el=document.getElementById(h.slice(1));
      if(el) setTimeout(()=>el.scrollIntoView(),0);
    }
  },[view]);
  useEffect(()=>{
    if(view) return;
    const ids=["top","research","work","contact"];
    const els=ids.map(i=>document.getElementById(i)).filter(Boolean);
    if(!els.length) return;
    const obs=new IntersectionObserver((es)=>es.forEach(e=>{if(e.isIntersecting)setActive(e.target.id);}),
      {rootMargin:"-45% 0px -50% 0px",threshold:0});
    els.forEach(el=>obs.observe(el));
    return ()=>obs.disconnect();
  },[view]);

  const cur = useRef(null);
  useEffect(()=>{
    const fine = window.matchMedia("(hover:hover) and (pointer:fine)").matches;
    const reduce = window.matchMedia("(prefers-reduced-motion:reduce)").matches;
    if(!fine || reduce || !cur.current) return;
    const root=document.querySelector(".pf"); root.classList.add("cur-on");
    const el=cur.current;
    const ret=el.querySelector(".ret"), rd=el.querySelector(".rd");
    let tx=innerWidth/2, ty=innerHeight/2, cx=tx, cy=ty, shown=false, hot=false, raf;
    const pad=n=>String(Math.max(0,Math.round(n))).padStart(4,"0");
    const move=e=>{
      tx=e.clientX; ty=e.clientY;
      if(!shown){shown=true; el.classList.add("show");}
      hot = !!(e.target && e.target.closest && e.target.closest("a,button"));
      el.classList.toggle("hot", hot);
    };
    const leave=()=>{ shown=false; el.classList.remove("show"); };
    const loop=()=>{
      cx+=(tx-cx)*0.28; cy+=(ty-cy)*0.28;
      ret.style.transform=`translate(${cx}px,${cy}px)`;
      const nearR=cx>innerWidth-110, nearB=cy>innerHeight-26;
      rd.style.transform=`translate(${cx+(nearR?-100:10)}px,${cy+(nearB?-16:8)}px)`;
      rd.textContent = hot ? "OPEN ↳" : `X ${pad(cx)} · Y ${pad(cy)}`;
      raf=requestAnimationFrame(loop);
    };
    window.addEventListener("pointermove",move,{passive:true});
    window.addEventListener("pointerdown",move,{passive:true});
    document.addEventListener("mouseleave",leave);
    window.addEventListener("blur",leave);
    raf=requestAnimationFrame(loop);
    return ()=>{
      cancelAnimationFrame(raf);
      window.removeEventListener("pointermove",move);
      window.removeEventListener("pointerdown",move);
      document.removeEventListener("mouseleave",leave);
      window.removeEventListener("blur",leave);
      root.classList.remove("cur-on");
    };
  },[]);

  const cw = view ? WORK.find(x=>x.ref===view) : null;
  const cwIdx = cw ? WORK.indexOf(cw) : -1;
  const prev = cwIdx>0 ? WORK[cwIdx-1] : null;
  const next = (cwIdx>=0 && cwIdx<WORK.length-1) ? WORK[cwIdx+1] : null;

  return (
    <div className="pf">
      <style>{CSS}</style>

      <div className="cur" ref={cur} aria-hidden="true">
        <span className="ret"><i className="l"/><i className="r"/></span>
        <span className="rd"/>
      </div>

      <nav className="nav" aria-label="Primary">
        <a href="#top" className="brand"><span className="sq" aria-hidden="true"/>M. Cavagna</a>
        <div className="right">
          <div className="links">
            {NAV.map(([id,l])=><a key={id} href={"#"+id} className={active===id?"on":""}>{l}</a>)}
          </div>
          <a className="cv" href={CV} download="Mariachiara_Cavagna_CV.pdf">CV ↓</a>
        </div>
      </nav>

      <div className="sheet">
        <span className="crop tl" aria-hidden="true"/><span className="crop tr" aria-hidden="true"/>

        <div className="scale" aria-hidden="true">
          <span className="cap">Portfolio · Rev 2026.1</span>
          <span className="cap r">Scale 1:1</span>
        </div>

        {cw ? (
          <CaseStudy w={cw} prev={prev} next={next} onHome={goHome} onCase={goCase}/>
        ) : (
        <>
        <header id="top" className="hero">
          <div className="L">
            <div className="doc">Doc · Portfolio / 2026 &nbsp;·&nbsp; Sheet 00 - Index</div>
            <h1 className="nameSm">Mariachiara Cavagna</h1>
            <p className="subs">
              <span className="a">Computer Science</span>
              <span className="d"> - </span>Product Design
              <span className="d"> - </span>ML Research
            </p>
            <p className="tag">
              Product designer with an industrial-design background, now working across data
              science and machine-learning research.
            </p>
            <div className="tblock">
              <div className="tbcap">Title block</div>
              <div className="tb" role="table" aria-label="Title block">
                <div className="cell"><div className="v">London, UK</div></div>
                <div className="cell"><div className="v">Product Design - Computer Science - ML Research</div></div>
                <div className="cell"><div className="v">Computer Science MSc · Queen Mary University of London<br/><span className="acc">Thesis - ML auto-tagging for text-to-music &amp; music-to-text retrieval</span></div></div>
              </div>
            </div>
          </div>
          <div className="R">
            <figure className="pcard">
              <div className="plate">
                <Ticks/>
                <img src={PHOTO} alt="Mariachiara Cavagna"/>
                <span className="fig">Fig · 00</span>
              </div>
            </figure>
          </div>
        </header>

        <section id="research" aria-label="Research">
          <div className="band">
            <span className="sh">Sheet 01</span><span className="ti">Research</span>
            <span className="ct">Data analytics · ML · [ 02 items ]</span>
          </div>
          <div className="rgrid">
          {PAPERS.map((p,i)=>(
            <article className="item" key={p.ref}>
              <div className="gut">
                <span className="ref">{p.ref}<span className="tot">/{String(PAPERS.length).padStart(2,"0")}</span></span>
                <span className="pill">{p.pill||"Paper"}</span>
              </div>
              <div className="main">
                <div>
                  <h3 className="wtitle" style={{fontSize:"clamp(1.05rem,2vw,1.5rem)",textTransform:"none",lineHeight:1.14}}>{p.title}</h3>
                  <div className="wrole">{p.venue} · {p.year}</div>
                  <p className="wdesc" style={{maxWidth:"60ch"}}>{p.abstract}</p>
                  {(p.dataset||p.contrib) && (
                    <div className="spec" style={{maxWidth:560}}>
                      {p.dataset && <div className="row"><div className="k">Dataset</div><div className="v">{p.dataset}</div></div>}
                      {p.contrib && <div className="row"><div className="k">Contrib.</div><div className="v">{p.contrib}</div></div>}
                    </div>
                  )}
                </div>
                <div>
                  {p.metrics && (
                    <div className="rd">
                      {p.metrics.map(([k,v])=>(
                        <div className="m" key={k}><div className="k">{k}</div><div className="v">{v}</div></div>
                      ))}
                    </div>
                  )}
                  {p.url!==null && (
                    <a className="readlink" href={p.url||"#research"}
                       target={p.url?"_blank":undefined} rel="noreferrer"
                       onClick={p.url?undefined:e=>e.preventDefault()}>
                      <span>Read paper</span><span className="v">{p.url?"↗":"Link soon"}</span>
                    </a>
                  )}
                </div>
              </div>
            </article>
          ))}
          </div>
        </section>

        <section id="work" aria-label="Products">
          <div className="band">
            <span className="sh">Sheet 02</span><span className="ti">Products</span>
            <span className="ct">Product design · [ 03 items ]</span>
          </div>
          <div className="wgrid">
            {WORK.map((w,i)=><WorkCard key={w.ref} w={w} n={i+1} total={WORK.length} onCase={goCase}/>)}
          </div>
        </section>

        <section id="contact" className="contact" aria-label="Contact">
          <div className="band" style={{padding:"0 0 20px",border:"none"}}>
            <span className="sh">Sheet 03</span><span className="ti">Contact</span>
            <span className="ct">End of document</span>
          </div>
          <div className="clist">
            <a href="mailto:m.cavagna@se25.qmul.ac.uk"><div className="ck">Email</div><div className="cv2">m.cavagna@se25.qmul.ac.uk</div></a>
            <a href="https://www.linkedin.com/in/mariachiara-cavagna" target="_blank" rel="noreferrer"><div className="ck">LinkedIn</div><div className="cv2">mariachiara-cavagna ↗</div></a>
            <a href="https://github.com/mariachiaracavagna" target="_blank" rel="noreferrer"><div className="ck">GitHub</div><div className="cv2">mariachiaracavagna ↗</div></a>
            <a href={CV} download="Mariachiara_Cavagna_CV.pdf"><div className="ck">Curriculum</div><div className="cv2 acc">Download CV ↓</div></a>
          </div>
          <div className="colophon">
            <span>© 2026</span><span>London, UK</span>
            <span>Set in Archivo &amp; Space Mono</span><span>Sheet 03 / 03 · Rev 2026.1</span>
          </div>
        </section>
        </>
        )}
      </div>
    </div>
  );
}
